"""Cold-read recipes per dense weight size on the H200 (generated by problems/muse_bf16_proj/dev/stream_roof/build.py)."""
SR_CUDA = '// Cold-read recipes for one weight buffer (the dense roles\' sizes): what rate a byte-bound stage can target.\n// gs: grid-stride 16 B non-allocating loads, U per thread in flight; chunk: each CTA one contiguous slice;\n// tma: each CTA one contiguous slice through a ring of ST bulk copies (cp.async.bulk + mbarrier) of CH bytes.\n#include <cuda_runtime.h>\n#include <stdint.h>\n#include <stdexcept>\n\nnamespace roof {\n__device__ __forceinline__ uint4 ldnc(const uint4* p) {\n  uint4 v;\n  asm volatile("ld.global.nc.L1::no_allocate.v4.u32 {%0,%1,%2,%3}, [%4];"\n               : "=r"(v.x), "=r"(v.y), "=r"(v.z), "=r"(v.w) : "l"(p));\n  return v;\n}\ntemplate <int U>\n__global__ void gs(const uint4* __restrict__ W, size_t n16, unsigned* sink) {\n  const size_t tid = (size_t)blockIdx.x * blockDim.x + threadIdx.x, step = (size_t)gridDim.x * blockDim.x;\n  unsigned acc = 0;\n  for (size_t i = tid; i < n16; i += step * U) {\n    uint4 v[U];\n#pragma unroll\n    for (int j = 0; j < U; ++j) { const size_t k = i + j * step; v[j] = k < n16 ? ldnc(W + k) : make_uint4(0, 0, 0, 0); }\n#pragma unroll\n    for (int j = 0; j < U; ++j) acc ^= v[j].x ^ v[j].y ^ v[j].z ^ v[j].w;\n  }\n  if (acc == 0x9e3779b9u) sink[0] = acc;\n}\ntemplate <int U>\n__global__ void chunk(const uint4* __restrict__ W, size_t n16, unsigned* sink) {\n  const size_t per = (n16 + gridDim.x - 1) / gridDim.x, lo = blockIdx.x * per, hi = lo + per < n16 ? lo + per : n16;\n  unsigned acc = 0;\n  for (size_t i = lo + threadIdx.x; i < hi; i += (size_t)blockDim.x * U) {\n    uint4 v[U];\n#pragma unroll\n    for (int j = 0; j < U; ++j) { const size_t k = i + (size_t)j * blockDim.x; v[j] = k < hi ? ldnc(W + k) : make_uint4(0, 0, 0, 0); }\n#pragma unroll\n    for (int j = 0; j < U; ++j) acc ^= v[j].x ^ v[j].y ^ v[j].z ^ v[j].w;\n  }\n  if (acc == 0x9e3779b9u) sink[0] = acc;\n}\n__device__ __forceinline__ uint32_t sa(const void* p) { return (uint32_t)__cvta_generic_to_shared(p); }\ntemplate <int ST>\n__global__ void tma(const uint8_t* __restrict__ W, size_t bytes, int ch, unsigned* sink) {\n  extern __shared__ __align__(128) uint8_t sm[];\n  __shared__ __align__(8) uint64_t bar[ST];\n  const size_t per = ((bytes + gridDim.x - 1) / gridDim.x + 15) / 16 * 16;\n  const size_t lo = blockIdx.x * per;\n  const size_t hi = lo + per < bytes ? lo + per : bytes;\n  if (lo >= hi) return;\n  const int n = (int)((hi - lo + ch - 1) / ch);\n  if (threadIdx.x == 0) {\n#pragma unroll\n    for (int s = 0; s < ST; ++s) asm volatile("mbarrier.init.shared::cta.b64 [%0], 1;" :: "r"(sa(&bar[s])) : "memory");\n    asm volatile("fence.mbarrier_init.release.cluster;" ::: "memory");\n  }\n  __syncthreads();\n  auto issue = [&](int i) {\n    const int s = i % ST;\n    const size_t off = lo + (size_t)i * ch;\n    const unsigned sz = (unsigned)((size_t)ch < hi - off ? (size_t)ch : hi - off);\n    asm volatile("{ .reg .b64 st; mbarrier.arrive.expect_tx.shared::cta.b64 st, [%0], %1; }" :: "r"(sa(&bar[s])), "r"(sz) : "memory");\n    asm volatile("cp.async.bulk.shared::cluster.global.mbarrier::complete_tx::bytes [%0], [%1], %2, [%3];"\n                 :: "r"(sa(sm + (size_t)s * ch)), "l"(W + off), "r"(sz), "r"(sa(&bar[s])) : "memory");\n  };\n  if (threadIdx.x == 0)\n    for (int i = 0; i < (ST < n ? ST : n); ++i) issue(i);\n  unsigned acc = 0;\n  for (int i = 0; i < n; ++i) {\n    const int s = i % ST;\n    const uint32_t ph = (uint32_t)((i / ST) & 1);\n    uint32_t done = 0;\n    do {\n      asm volatile("{ .reg .pred p; mbarrier.try_wait.parity.shared::cta.b64 p, [%1], %2; selp.u32 %0, 1, 0, p; }"\n                   : "=r"(done) : "r"(sa(&bar[s])), "r"(ph) : "memory");\n    } while (!done);\n    acc ^= *reinterpret_cast<const unsigned*>(sm + (size_t)s * ch + ((threadIdx.x * 16) % ch));\n    __syncthreads();\n    if (threadIdx.x == 0 && i + ST < n) issue(i + ST);\n  }\n  if (acc == 0x9e3779b9u) sink[0] = acc;\n}\n}  // namespace roof\n\nstatic void check() {\n  cudaError_t e = cudaGetLastError();\n  if (e != cudaSuccess) throw std::runtime_error(cudaGetErrorString(e));\n}\n\n// kind 0 = gs, 1 = chunk (arg = U: 4 or 8); kind 2 = tma (arg = ST: 2, 3, 4, 6, 8; ch bytes per stage)\nvoid rd(int64_t kind, int64_t W, int64_t bytes, int64_t sink, int64_t ctas, int64_t threads, int64_t arg, int64_t ch,\n        int64_t stream) {\n  cudaStream_t s = reinterpret_cast<cudaStream_t>(stream);\n  const size_t n16 = (size_t)bytes / 16;\n  if (kind == 0) {\n    if (arg == 4) roof::gs<4><<<(int)ctas, (int)threads, 0, s>>>((const uint4*)W, n16, (unsigned*)sink);\n    else roof::gs<8><<<(int)ctas, (int)threads, 0, s>>>((const uint4*)W, n16, (unsigned*)sink);\n  } else if (kind == 1) {\n    if (arg == 4) roof::chunk<4><<<(int)ctas, (int)threads, 0, s>>>((const uint4*)W, n16, (unsigned*)sink);\n    else roof::chunk<8><<<(int)ctas, (int)threads, 0, s>>>((const uint4*)W, n16, (unsigned*)sink);\n  } else {\n    const size_t smem = (size_t)arg * ch;\n#define ROOF_TMA(N)                                                                                              \\\n  if (arg == N) {                                                                                                \\\n    if (cudaFuncSetAttribute(roof::tma<N>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem) != cudaSuccess) \\\n      throw std::runtime_error("smem");                                                                          \\\n    roof::tma<N><<<(int)ctas, (int)threads, smem, s>>>((const uint8_t*)W, (size_t)bytes, (int)ch, (unsigned*)sink); \\\n  }\n    ROOF_TMA(2) ROOF_TMA(3) ROOF_TMA(4) ROOF_TMA(6) ROOF_TMA(8)\n#undef ROOF_TMA\n  }\n  check();\n}\n'

import statistics
import time

import torch
from torch.utils.cpp_extension import load_inline as _sr_load

_SR = []


def sr_ext():
    if not _SR:
        major, minor = torch.cuda.get_device_capability()
        arch = '90a' if major == 9 else f'{major}{minor}'
        _SR.append(_sr_load(name=f'muse_lab_stream_roof_{arch}', cuda_sources=SR_CUDA, functions=['rd'], verbose=False,
                            cpp_sources='#include <cstdint>\nvoid rd(int64_t, int64_t, int64_t, int64_t, int64_t, int64_t, int64_t, int64_t, int64_t);',
                            extra_cuda_cflags=['-O3', '-std=c++20', f'-gencode=arch=compute_{arch},code=sm_{arch}']))
    return _SR[0]


def _sr_graph(fn):
    s = torch.cuda.Stream()
    s.wait_stream(torch.cuda.current_stream())
    with torch.cuda.stream(s):
        for _ in range(2):
            fn()
    torch.cuda.current_stream().wait_stream(s)
    torch.cuda.synchronize()
    g = torch.cuda.CUDAGraph()
    with torch.cuda.graph(g):
        fn()
    g.replay()
    torch.cuda.synchronize()
    return g


def _sr_times(graphs, rounds):
    evs = []
    for r in range(rounds):
        order = list(range(len(graphs)))
        if r % 2:
            order.reverse()
        for j in order:
            lab_cold_l2()  # h200_lab: the judge's cold-L2 step (1 GiB read)
            a, b = torch.cuda.Event(enable_timing=True), torch.cuda.Event(enable_timing=True)
            a.record()
            graphs[j].replay()
            b.record()
            evs.append((j, a, b))
    torch.cuda.synchronize()
    vals = [[] for _ in graphs]
    for j, a, b in evs:
        vals[j].append(a.elapsed_time(b) * 1e3)
    return [statistics.median(v) for v in vals]


def sr_arms(sms):
    arms = []
    for ctas, thr, u in ((1, 1024, 4), (1, 1024, 8), (2, 512, 4), (2, 1024, 4), (4, 256, 4), (4, 256, 8), (4, 512, 4),
                         (8, 256, 4), (8, 256, 8)):
        arms.append((f'gs/{ctas * sms}/{thr}/{u}', 0, ctas * sms, thr, u, 0))
    for ctas, thr, u in ((1, 1024, 4), (2, 512, 4), (4, 256, 4), (4, 256, 8)):
        arms.append((f'ch/{ctas * sms}/{thr}/{u}', 1, ctas * sms, thr, u, 0))
    for ctas, st, ch in ((1, 8, 16384), (1, 4, 32768), (1, 3, 65536), (1, 6, 32768), (2, 6, 16384), (2, 3, 32768),
                         (2, 4, 16384), (4, 4, 8192), (4, 3, 16384)):
        arms.append((f'tma/{ctas * sms}/{st}x{ch // 1024}K', 2, ctas * sms, 128, st, ch))
    return arms


def lab(deadline, weights):
    t0 = time.monotonic()
    dev = weights['o'].device
    sms = torch.cuda.get_device_properties(dev).multi_processor_count
    ext = sr_ext()
    sink = torch.zeros(4, dtype=torch.int32, device=dev)
    router = weights['router'].float()
    hi = router.to(torch.bfloat16)
    bufs = [('unpool_slice', weights['unpooler'][:1024].contiguous()), ('o', weights['o'].contiguous()),
            ('qkv', weights['qkv_gate'].contiguous()), ('unpooler', weights['unpooler'].contiguous()),
            ('pool_router', torch.cat([weights['pooler'], hi, (router - hi.float()).to(torch.bfloat16)], 0).contiguous())]
    empty = _sr_graph(lambda: None)
    base = _sr_times([empty], 8)[0]
    lines = [f'META cold reads (lab_cold_l2 per replay) of each dense weight; us = median of 16 minus an empty graph '
             f'({base:.2f} us); TB/s = bytes / us; gs/CTAs/threads/U = grid-stride 16 B ld.nc, U in flight per thread; '
             'ch = same, one contiguous slice per CTA; tma/CTAs/STxCH = per-CTA slice through ST bulk copies of CH '
             '(cp.async.bulk + mbarrier, 128 threads); top 6 per size + the 528/256/4 baseline']
    for name, w in bufs:
        if time.monotonic() > deadline - 10:
            lines.append(f'SKIP {name}')
            continue
        nbytes = w.numel() * 2
        arms, rej = [], 0
        for label, kind, ctas, thr, arg, ch in sr_arms(sms):
            fn = lambda kind=kind, ctas=ctas, thr=thr, arg=arg, ch=ch: ext.rd(
                kind, w.data_ptr(), nbytes, sink.data_ptr(), ctas, thr, arg, ch, torch.cuda.current_stream().cuda_stream)
            try:
                fn()
                torch.cuda.synchronize()
            except Exception:
                rej += 1
                continue
            arms.append((label, fn))
        graphs = [_sr_graph(fn) for _, fn in arms]
        us = [max(u - base, 1e-3) for u in _sr_times(graphs, 16)]
        del graphs
        got = sorted(zip(us, (a for a, _ in arms)))
        ref = dict((a, u) for u, a in got).get(f'gs/{4 * sms}/256/4')
        cells = ' '.join(f'[{a} {u:.2f}us {nbytes / u / 1e6:.2f}TB/s]' for u, a in got[:6])
        lines.append(f'R {name} {nbytes / 1e6:.1f}MB base={ref:.2f}us {nbytes / ref / 1e6:.2f}TB/s | {cells} rej={rej}')
        torch.cuda.empty_cache()
    lines.append(f'END t={time.monotonic() - t0:.1f}s')
    return lines
